ANNOTATIONS = [
    (81, 'before', r'''getAgentNameToPoll：三种身份三条路。进程内队友返回 undefined（它们有 waitForNextPromptOrShutdown 专属通道，走这个 poller 会乱路由）；进程级队友用自己的 agent 名；leader 从 teammates 映射里查自己的名字；独立会话不轮询。'''),
    (94, 'before', r'''为什么进程内队友必须排除：它们和 leader 共享同一份 React context 和 AppState（共用 setAppState），leader 的 REPL 重渲染可能跑在队友的 AsyncLocalStorage 上下文里。这里返回 undefined 优雅跳过而不是抛错。'''),
    (107, 'after', r'''1s 轮询间隔。文件系统邮箱没有事件通知机制，只能拉；1s 是「跟手感」和「别把磁盘扫烫」之间的折中。'''),
    (116, 'after', r'''Props 里的 onSubmitMessage 是死代码消除的产物：原名含 teammate 字样，external 构建会把整个字符串模式匹配掉，于是参数改名保命。函数体内第一行又改回可读的名字。'''),
    (126, 'before', r'''useInboxPoller 的总线职责：每秒拉一次未读，按消息类型分拣成九路，leader 侧和 worker 侧各领各的任务，常规消息则按空闲/忙碌决定立即提交还是排队。两段式结构（poll 处理新消息 + effect 在空闲时投递排队消息）合起来保证「忙碌中到达的消息不丢、空闲时补投」。'''),
    (133, 'after', r'''函数体内改名回 onSubmitTeammateMessage——可读性和 DCE 各取一半。'''),
    (136, 'after', r'''只订阅 inbox.messages.length 而不是整个 appState 对象：这个 hook 挂在顶层，订阅大会把每次无关状态变化都拖成重渲染。'''),
    (139, 'before', r'''poll 主体。所有 appState 读取都走 store.getState() 而不是 hook 订阅——poll 是 useCallback，依赖 appState 对象会造成无限循环。'''),
    (152, 'after', r'''读到未读就开工；没有直接返回，连 markRead 都不用（没有新状态）。'''),
    (158, 'before', r'''计划批准只认 team-lead 发的：队友之间可以互相伪造批准消息提前退出计划模式，所以 from 字段是硬校验，不是提示。'''),
    (202, 'after', r'''markRead 的时机是全文件第二重要的设计：消息送达或可靠入队之后才标记。在此之前崩溃，下一轮 poll 会重读同一条消息，不会静默丢失。'''),
    (216, 'before', r'''九路分拣：权限请求/权限响应/沙箱权限请求/沙箱权限响应/关机请求/关机批准/团队权限更新/模式设置/计划批准，剩下的是常规消息。顺序即优先级——每条消息只进一个桶，解析函数是带类型的 XML/JSON 判别式。'''),
    (251, 'before', r'''leader 侧处理权限请求：把 tmux worker 的请求塞进标准 ToolUseConfirmQueue，这样分屏 worker 也能拿到和进程内队友一模一样的工具专属 UI（BashPermissionRequest、FileEditToolDiff 等），不需要为 worker 单开一套渲染。'''),
    (266, 'before', r'''队列不可用（leader 侧没挂载）就丢弃并记日志——worker 会一直等下去直到自己超时，但 leader 不能崩。'''),
    (294, 'before', r'''ToolUseConfirm entry 的四个回调把 leader 的决定经 mailbox 送回 worker：abort/reject 都是 rejected，allow 额外带回更新后的输入和权限变更。recheckPermission 对 tmux worker 是 no-op——权限状态在 worker 那边，leader 侧重查没有意义。'''),
    (340, 'before', r'''按 toolUseID 去重：上一轮 markMessagesAsRead 失败的话同一消息会被重读，不判重就会弹出两个重复对话框。'''),
    (354, 'before', r'''桌面通知只对第一条请求发，且 isLoading / 有对话框聚焦时静音——忙碌时每秒一条通知等于没有通知。'''),
    (368, 'before', r'''worker 侧处理权限响应：hasPermissionCallback(requestId) 是门——没注册回调说明请求早已超时清理，响应直接丢弃，不会唤醒一个不存在的等待。'''),
    (400, 'before', r'''leader 侧处理沙箱权限请求（worker 要访问某主机）：进 AppState.workerSandboxPermissions.queue，由专门的面板渲染。'''),
    (422, 'before', r'''畸形消息防护：hostPattern.host 缺失就跳过。队友进程可能崩在写一半的消息上，leader 不能跟着崩。'''),
    (449, 'after', r'''入队后同样只对第一条发通知，静音条件与权限请求一致。'''),
    (467, 'before', r'''worker 侧处理沙箱响应：命中回调就处理并清掉 pendingSandboxRequest 指示器（UI 上「等待网络授权」的角标）。'''),
    (499, 'before', r'''worker 侧处理团队权限更新：leader 批量下发的 allow 规则，应用为 session 级 alwaysAllowRules。同样是先校验 rules/behavior 存在再 apply。'''),
    (551, 'before', r'''worker 侧处理模式设置：同样只信 team-lead。除了改本地权限上下文，还回写 team 文件的 memberMode——leader 的面板要显示每个队友当前的 mode，不回写就永远是旧的。'''),
    (600, 'before', r'''leader 侧处理计划批准请求：默认自动批准（leader 已经在排队等队友的计划了，再弹一次框是双重确认），批准响应经 mailbox 回写。modeToInherit 有个细节：leader 自己是 plan 模式时给队友 default——plan 不传染，否则两个人都憋在计划里没人干活。'''),
    (620, 'before', r'''批准走两条路：mailbox 通知（进程级队友）+ in-process task 状态更新（进程内队友）。findInProcessTeammateTaskId 找不到 taskId 就只发 mailbox，两种队友形态都覆盖。'''),
    (649, 'after', r'''批准发完仍把原消息塞回 regularMessages——队友需要从上下文里知道「我的计划被批了」，而不只是状态机跳变。'''),
    (666, 'before', r'''worker 侧收到关机请求：保留 JSON 原文透传给 UI 组件渲染，模型侧的指令来自工具提示词文档，不需要在这里改写文本。'''),
    (679, 'before', r'''leader 侧收到关机批准：杀 pane（有 paneId 的话）+ 把队友从 teamContext.teammates 摘掉 + 任务改完成态 + inbox 里插一条 system 通知。四件事一件都不能少，少了任何一个 UI 就会显示幽灵队友。'''),
    (691, 'before', r'''杀 pane 前先确保后端类注册（纯 import，不起子进程探测），insideTmux 决定传参——在 tmux 内杀自己的子 pane 和从外面杀，参数语义不同。'''),
    (749, 'before', r'''补完成态是 tmux 专属补丁：进程内队友有自己的 runner 置 completed，tmux worker 没有——不补的话 hasRunningTeammates 永远为真，转圈永远不停。'''),
    (790, 'after', r'''system 通知消息进 inbox（teammate_terminated 类型），用户看到的是「XX 已停机」而不是一条静默消失。'''),
    (803, 'before', r'''没有常规消息也要 markRead：权限/关机这类消息处理完同样要清未读标记，否则每秒重读重处理一遍。'''),
    (820, 'after', r'''XML 包装（teammate-message 标签）+ color/summary 属性透传：模型需要知道消息是谁发的、什么颜色徽章、摘要是什么，UI 回放也要用。'''),
    (843, 'before', r'''空闲立即提交，忙碌进 AppState.inbox 排队。注意 onSubmitTeammateMessage 返回 false（query 已在跑）时也要排队——提交被拒不是消息消失。'''),
    (864, 'after', r'''markRead 卡在最后：只有「已提交」或「已可靠入队」两种命运才会走到这里。崩溃在中间 → 下一轮重读，消息不丢。'''),
    (876, 'before', r'''第二个 effect：会话从忙碌转空闲时投递排队消息。processed 状态的消息（回合中作为附件已投递过）直接清掉；pending 的格式化后尝试提交，失败就继续排队。'''),
    (954, 'after', r'''非队友非 leader 时给 useInterval 传 null——usehooks-ts 的约定，null 即停表，比自己包一层 shouldPoll 判断干净。'''),
    (958, 'before', r'''挂载时补一次初始 poll（useInterval 不会立刻触发）。ref 守卫保证只跑一次，且同样用 store.getState() 避免 appState 依赖。'''),
]
